{
  "name": "内部系统伪设备",
  "name_en": "Internal system pseudo-device",
  "manufacturer": "",
  "description": "一种无独立硬件实体的系统状态伪设备，用于把主机操作系统的内部信息或服务抽象为可监测的逻辑输入，例如网络连通性、处理器温度、系统负载、时钟时间段和磁盘占用。在实验自动化中常用于状态监测、条件触发和联动控制。",
  "description_en": "A pseudo-device with no standalone hardware representation, used to expose host operating-system state or services as monitorable logical inputs, such as network reachability, CPU temperature, system load, time-of-day windows, and disk usage. In lab automation, it is commonly used for status monitoring, conditional triggering, and event-driven coordination.",
  "tag_hints": [
    "system monitoring",
    "pseudo-device",
    "network reachability",
    "CPU temperature",
    "load average",
    "time-based triggering",
    "disk usage"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭内部系统伪设备并停止监测。",
      "description_en": "Close the internal system pseudo-device and stop monitoring."
    },
    {
      "action_name": "auto-closed",
      "description": "获取设备是否已关闭。",
      "description_en": "Get whether the device is closed."
    },
    {
      "action_name": "auto-event_delay",
      "description": "获取轮询间隔。",
      "description_en": "Get the polling interval."
    },
    {
      "action_name": "auto-wait_for_active",
      "description": "等待设备变为活动状态。",
      "description_en": "Wait for the device to become active."
    },
    {
      "action_name": "auto-wait_for_inactive",
      "description": "等待设备变为非活动状态。",
      "description_en": "Wait for the device to become inactive."
    },
    {
      "action_name": "auto-host",
      "description": "获取目标主机名或 IP 地址。",
      "description_en": "Get the target hostname or IP address."
    },
    {
      "action_name": "auto-value",
      "description": "获取归一化数值。",
      "description_en": "Get the normalized value."
    },
    {
      "action_name": "auto-temperature",
      "description": "获取处理器温度。",
      "description_en": "Get the CPU temperature."
    },
    {
      "action_name": "auto-is_active",
      "description": "获取设备当前是否处于活动状态。",
      "description_en": "Get whether the device is currently active."
    },
    {
      "action_name": "auto-load_average",
      "description": "获取系统负载平均值。",
      "description_en": "Get the system load average."
    },
    {
      "action_name": "auto-start_time",
      "description": "获取活动时间段的开始时间。",
      "description_en": "Get the start time of the active time window."
    },
    {
      "action_name": "auto-end_time",
      "description": "获取活动时间段的结束时间。",
      "description_en": "Get the end time of the active time window."
    },
    {
      "action_name": "auto-utc",
      "description": "获取是否使用协调世界时。",
      "description_en": "Get whether Coordinated Universal Time is used."
    },
    {
      "action_name": "auto-usage",
      "description": "获取磁盘空间使用率。",
      "description_en": "Get the disk usage percentage."
    }
  ]
}

